/**
 * Typed Postgres access (Drizzle over the Supabase session pooler).
 * schema.ts / relations.ts are generated by `db:pull` — don't edit them by hand.
 * This connection bypasses RLS, so every query must scope by user id itself.
 *
 * Hot paths (Scripture search, citation checks) also use this connection rather
 * than Supabase REST: a long-lived connection stays warm (~150ms), while REST's
 * pooled connections go cold after idling and the first search can take seconds.
 */
import { drizzle } from "drizzle-orm/postgres-js";
import postgres from "postgres";
import { env } from "../env";
import * as relations from "./relations";
import * as schema from "./schema";

if (!env.DATABASE_URL) {
  throw new Error("DATABASE_URL is not set in apps/server/.env (needed for chat and search).");
}

/** Raw tagged-template client. Connections are kept open (no idle timeout). */
export const pg = postgres(env.DATABASE_URL, { max: 5, idle_timeout: 0, connect_timeout: 10 });
export const db = drizzle(pg, { schema: { ...schema, ...relations } });
export { schema };

// A tiny query now and then so the pooler never drops the warm connection.
setInterval(() => {
  pg`select 1`.catch(() => {});
}, 120_000).unref();
